package com.sakan.iptv;
import org.junit.*;import static org.junit.Assert.*;import org.json.*;import java.nio.charset.StandardCharsets;import java.util.*;
public class VodMetadataTest {
 private ProviderTest fixture;
 @Before public void start()throws Exception{fixture=new ProviderTest();fixture.setup();fixture.server.createContext("/",e->{String q=e.getRequestURI().getRawQuery();String result=q.contains("get_vod_info")?"{\"info\":{\"movie_image\":\"https://img.test/movie.jpg\",\"duration_secs\":1800},\"movie_data\":{\"container_extension\":\"mkv\",\"direct_source\":\"https://cdn.test/movie.php?id=9\"}}":q.contains("get_series_info")?"{\"info\":{\"cover\":\"https://img.test/series.jpg\"},\"episodes\":{\"1\":[{\"id\":77,\"title\":\"Episode\",\"container_extension\":\"\",\"direct_source\":\"https://cdn.test/episode.m3u8\",\"info\":{\"container_extension\":\"mkv\",\"duration_secs\":2400}}]}}":"{}";byte[] b=result.getBytes(StandardCharsets.UTF_8);e.sendResponseHeaders(200,b.length);e.getResponseBody().write(b);e.close();});}
 @After public void stop(){fixture.stop();}
 private Provider provider()throws Exception{return new Provider(new JSONObject().put("mode","XTREAM").put("url",fixture.url).put("user","user").put("pass","pass"));}
 @Test public void movieInfoRepairsMissingExtensionAndPrefersProviderDirectSource()throws Exception{Provider p=provider();Provider.Item movie=new Provider.Item("9","Movie","1","","null",false);List<String> urls=p.streams(movie,"vod","auto");assertEquals("https://cdn.test/movie.php?id=9",urls.get(0));assertTrue(urls.stream().anyMatch(u->u.endsWith("/9.mkv")));assertEquals(1800,movie.durationSeconds);assertEquals("https://img.test/movie.jpg",movie.cover);}
 @Test public void episodesUseInfoExtensionDirectSourceAndInheritedPoster()throws Exception{Provider p=provider();Provider.Item episode=p.episodes(new Provider.Item("5","Show","1","","",true)).get(0);assertEquals("mkv",episode.ext);assertEquals("5",episode.parentId);assertEquals("https://img.test/series.jpg",episode.cover);assertEquals(2400,episode.durationSeconds);assertEquals("https://cdn.test/episode.m3u8",p.streams(episode,"series","auto").get(0));Provider.Item restored=Provider.restored(episode.json("series",false));assertEquals("5",restored.parentId);assertEquals("https://cdn.test/episode.m3u8",p.streams(restored,"series","auto").get(0));}
 @Test public void extensionNormalizationNeverCreatesNullOrPathFragments(){assertEquals("mp4",Provider.mediaExtension(""));assertEquals("mp4",Provider.mediaExtension("null"));assertEquals("mp4",Provider.mediaExtension("../secret"));assertEquals("mkv",Provider.mediaExtension(".MKV"));}
}
